bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';
import {readFileSync} from 'node:fs';
const e=process.env;
const pw=readFileSync('/run/secrets/videobot_db_password','utf8').trim();
const token=readFileSync('/run/secrets/videobot_telegram_token','utf8').trim();
const db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:pw,max:1,connectionTimeoutMillis:5000});
const stage={done:[]};
try{
 const {rows}=await db.query("SELECT l.thumbnail_file_id,l.sample_file_id,b.free_message_ids,b.paid_message_id,b.topic_id FROM videobot_post_receipts b JOIN videobot_listings l ON l.listing_id=b.listing_id AND l.revision=b.revision WHERE b.paid_message_id=4691 AND b.free_message_ids=ARRAY[4689,4690]::bigint[] AND b.status='sent'");
 if(rows.length!==1)process.exit(61);
 const r=rows[0];
 if(!r.thumbnail_file_id||!r.sample_file_id||Number(r.paid_message_id)!==4691||Number(r.topic_id)<1)process.exit(62);
 const targets=[
  {message_id:4689,type:'photo',file:r.thumbnail_file_id},
  {message_id:4690,type:'video',file:r.sample_file_id}
 ];
 for(let i=0;i<targets.length;i++){
  const t=targets[i];
  const params={chat_id:-1002373696859,message_id:t.message_id,media:{type:t.type,media:t.file,has_spoiler:true}};
  const res=await fetch('https://api.telegram.org/bot'+token+'/editMessageMedia',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(params),signal:AbortSignal.timeout(30000)});
  const response=await res.json().catch(()=>null);
  if(response?.ok===true && response.result?.message_id===t.message_id && response.result?.has_media_spoiler===true){
   stage.done.push(t.message_id);continue;
  }
  if(res.status===400 && String(response?.description).toLowerCase()==='bad request: message is not modified'){
   stage.done.push(t.message_id);continue;
  }
  console.error('SPOILER_EDIT_REJECTED_STEP='+i+';DONE='+stage.done.length+';HTTP='+res.status);
  process.exit(70+i);
 }
 console.log('EXISTING_FREE_TWO_SPOILERS_APPLIED_OR_ALREADY_CURRENT=PASS');
 console.log('PAID_MESSAGE_4691_UNTOUCHED=PASS');
}catch(err){console.error('SPOILER_EDIT_EXCEPTION;DONE='+stage.done.length);process.exitCode=75}
finally{await db.end()}
JS
